@startuml

class Faculty {
  + Name : string
}

class Institute {
  + Name : string
  + Address : string
}

class Employee {
  + SocialSecurityNumber : string
  + Name : string
  + EmailAddress : string
}

class ResearchAssistant extends Employee {
  + FieldOfResearch : string
}

class Lecturer extends ResearchAssistant {}

class AdministrativeStaff extends Employee {}

class Project {
  + Name : string
  + StartDate : date
  + EndDate : date
}

class Course {
  + ID : int
  + Name : string
  + WeeklyDuration : int
}

class RAProjectAssignment {
  + Hours : int
}

Faculty "1" -- "*" Institute : consistsOf
Faculty "1" -- "1" Employee : headedBy
Employee "1" -- "*" Employee : totalEmployeesCount
ResearchAssistant "*" -- "1..*" Institute : assignedTo
ResearchAssistant "1" -- "*" RAProjectAssignment : involvedIn
RAProjectAssignment "*" -- "1" Project : partOf
Lecturer "1" -- "*" Course : teaches

@enduml

